    parts = s.split(".")
    if len(parts) < 2:
        return False
    for part in parts:
        if not (1 <= len(part) <= 63):
            return False
        if part[0] == "-" or part[-1] == "-":
            return False
        for ch in part:
            if not (ch.isalnum() or ch == "-"):
                return False
    tld = parts[-1]
    return tld.isalpha() and len(tld) >= 2
